 modal('Thanh toán phí vận chuyển / bốc xếp',`${select('chargeRef','Khoản cần thanh toán',[['','Chọn khoản phí'],...options],id||'')}${input('amount','Số tiền thanh toán (₫)',1,'number',true,'min="1" step="1"')}${select('method','Hình thức thanh toán',[['Chuyển khoản','Chuyển khoản'],['Tiền mặt','Tiền mặt']])}${input('reference','Mã giao dịch','', 'text', false)}${input('date','Ngày thanh toán',isoDay(new Date()),'date')}${evidenceField('Ảnh/PDF chứng từ chi phí')}`,'service-pay-form');break;
