function updatePricingPreview(){
 const form=document.getElementById('product-form'),el=document.getElementById('pricing-preview');if(!form||!el)return;
 const parent=form.querySelector('.pricing-info'),price=Number(parseVnd(form.querySelector('[name="price"]')?.value)||0),cost=Number(parent?.dataset.cost||0);
 if(!cost){el.textContent='Chưa có giá vốn từ hàng nhập để tính lãi gộp.';return;}
 const profit=price-cost,margin=price>0?profit/price*100:0;
 el.textContent=`Lãi gộp dự tính mỗi sản phẩm: ${money(profit)} · Biên gộp: ${margin.toFixed(1)}%`;
}

function updatePurchasePreview(){const f=document.getElementById('receive-form');if(!f)return;
 const fd=new FormData(f),q=Number(fd.get('quantity')||0),price=Number(parseVnd(fd.get('unitCost'))||0),freight=Number(parseVnd(fd.get('freight'))||0),handling=Number(parseVnd(fd.get('handling'))||0);
 const landed=q*price+freight+handling,owed=q*price+(fd.get('freightRecipient')==='supplier'?freight:0)+(fd.get('handlingRecipient')==='supplier'?handling:0);
 const node=document.getElementById('purchase-preview');if(!node)return;
 const valid=[q,price,freight,handling].every(x=>Number.isFinite(x)&&x>=0)&&q>0;
 node.innerHTML=valid?`<div><small>Giá vốn nhập kho / đơn vị (dự tính)</small><strong>${money(landed/q)}</strong></div><div><small>Giá trị nhập kho khi nhận</small><strong>${money(landed)}</strong></div><div><small>Phải trả nhà cung cấp khi nhận</small><strong>${money(owed)}</strong></div>`:'<span class="muted">Nhập số lượng và giá mua để xem dự tính.</span>';
}
function applyShippingPolicy(){const f=document.getElementById('receive-form');if(!f)return;const supplier=data.suppliers.find(s=>s.id===f.querySelector('[name="supplierId"]')?.value);if(!supplier)return;
 const total=Number(f.querySelector('[name="quantity"]')?.value||0)*Number(parseVnd(f.querySelector('[name="unitCost"]')?.value)||0);
 const free=supplier.shippingPolicy==='free'||supplier.shippingPolicy==='threshold'&&total>=Number(supplier.freeThreshold||0);
 const recipient=f.querySelector('[name="freightRecipient"]'),fee=f.querySelector('[name="freight"]');
 if(recipient)recipient.value=free?'none':supplier.shippingPolicy==='external'?'carrier':'supplier';
 if(fee)fee.value=formatVndInput(free?0:Number(supplier.shippingFee||0));
 const exp=f.querySelector('[name="expectedDelivery"]');if(exp&&supplier.deliveryDays&&!exp.value){const d=new Date();d.setDate(d.getDate()+Number(supplier.deliveryDays));exp.value=isoDay(d);}
 updatePurchasePreview();
}
function closeModal(){ui.modal='';ui.editing='';document.getElementById('modal-slot').innerHTML='';}
function action(act,id){switch(act){case 'view-evidence':void showEvidence(id);break;case 'attach-evidence':modal('Bổ sung chứng từ cho giao dịch đã ghi',`<input type="hidden" name="evidenceRef" value="${safe(id)}"><p class="caption">Đính kèm ảnh/PDF không ghi thêm tiền và không thay đổi công nợ.</p>${evidenceField('Chọn ảnh hoặc PDF biên lai cần lưu')}`,'attach-evidence-form');break;case 'mark-transit':transactional(s=>purchaseMarkTransit(s,id),'Đã ghi hàng đang vận chuyển.');break;case 'toggle-nav':ui.sidebar=!ui.sidebar;render();break;case 'close-nav':ui.sidebar=false;render();break;case 'close-modal':closeModal();break;case 'toggle-chat':ui.chatOpen=!ui.chatOpen;render();scrollChat();break;case 'add-line':document.getElementById('order-lines')?.insertAdjacentHTML('beforeend',orderLine());break;case 'remove-line':{const all=document.querySelectorAll('.order-line');if(all.length>1)event.target.closest('.order-line')?.remove();break;}case 'delete-expense':if(confirm('Xóa khoản chi này? Đây là thay đổi dữ liệu tài chính.'))transactional(s=>expenseDelete(s,id),'Đã xóa khoản chi.');break;case 'finance-ai':sendChat('Phân tích tình hình doanh thu, chi phí vận hành, dòng tiền trả nhà cung cấp, công nợ và lợi nhuận. Phân biệt dòng tiền với chi phí giá vốn, đưa ra tối đa 3 khuyến nghị có số liệu và rủi ro.');break;case 'go-finance':go('finance');break;case 'rank-to-decision':{const r=scoreSuppliers(data);if(!r.length)return;transactional(s=>decisionSave(s,{title:`Đánh giá chọn nhà cung cấp ${r[0].name}`,reason:`Xếp hạng đa tiêu chí: ${r[0].score.toFixed(2)}/5 (giá ${data.weights.price}, giao ${data.weights.delivery}, chất lượng ${data.weights.quality}). Điểm do người dùng nhập; cần xác minh thực tế.`,expected:'Xác minh chất lượng, giá và thời gian giao trước khi ký mua.',owner:'Quản lý mua hàng'}),'Đã lưu phương án vào quản lý quyết định.');go('decisions');break;}case 'suggest-replenishment':{const p=data.products.find(x=>x.id===id);if(!p)return;const q=Math.max(0,p.min-p.stock);transactional(s=>decisionSave(s,{title:`Đề xuất nhập bổ sung ${p.name}`,reason:`Tồn ${p.stock}, ngưỡng ${p.min}; số lượng tối thiểu để trở lại ngưỡng: ${q}. Ước vốn ${money(q*p.cost)}, chưa phải báo giá thực tế.`,expected:`Nâng tồn kho tới ngưỡng ${p.min}.`,owner:'Quản lý kho'}),'Đã lưu đề xuất, chưa tạo phiếu nhập tự động.');go('decisions');break;}case 'export-report':{const f=financials(data,ui.month);download('retailmind-bao-cao.csv','\ufeffChỉ tiêu,Giá trị\n'+[['Doanh thu',f.revenue],['Giá vốn đã biết',f.cogsKnown],['Chi phí vận hành',f.expenses],['Lợi nhuận',f.net===null?'Thiếu dữ liệu':f.net],['Đơn thiếu giá vốn',f.missing.length],['Giá trị tồn kho',inventoryValue(data)],['Đã chi nhà cung cấp',procurementSummary(data,ui.month).paidSupplier],['Đã chi phí nhập kho bên ngoài',procurementSummary(data,ui.month).paidExternal],['Tổng chi đã ghi nhận (mua hàng và hoạt động)',procurementSummary(data,ui.month).paidSupplier+procurementSummary(data,ui.month).paidExternal+f.expenses],['Công nợ NCC',data.suppliers.reduce((z,x)=>z+supplierDebt(data,x.id),0)],['Công nợ dịch vụ',procurementSummary(data).serviceDebt],['Phải thu khách',customerReceivables(data)],['Tiền đã thu khách',procurementSummary(data,ui.month).cashReceived]].map(([k,v])=>`"${k}","${v}"`).join('\n'),'text/csv;charset=utf-8');break;}case 'backup':void backupAll();break;case 'restore':document.getElementById('restore-file')?.click();break;case 'migrate':if(confirm('Bạn muốn chuyển dữ liệu RetailMind cũ trong cùng trình duyệt? Hãy xuất bản sao lưu v3 trước. Dữ liệu hiện tại sẽ được thay thế.')){try{setData(migrateLegacy(localStorage),'Đã chuyển dữ liệu cũ. Các đơn thiếu giá vốn sẽ được đánh dấu chưa xác minh.');}catch(e){notice(e.message,'bad');}}break;case 'reset-demo':if(confirm('Thay thế toàn bộ dữ liệu hiện tại bằng dữ liệu minh họa? Hãy xuất sao lưu trước.')){setData(seedDemo(),'Đã tạo dữ liệu mẫu mới.');}break;case 'reset-empty':if(confirm('Xóa toàn bộ dữ liệu phiên bản 3 trên trình duyệt này? Không thể hoàn tác nếu chưa sao lưu.')){if(confirm('Xác nhận lần cuối: bắt đầu bằng dữ liệu trống?'))setData(baseState(),'Đã bắt đầu với dữ liệu trống.');}break;case 'go-alerts':go('alerts');break;
 case 'go-purchase':go('suppliers');break;
 case 'go-ranking':go('ranking');break;
 case 'go-payment':go('suppliers');openModal('pay');break;
 case 'buy-product':go('suppliers');openModal('receive',id);break;
 case 'forecast-to-decision':{const p=data.products.find(x=>x.id===id),f=p?forecast(data,id):null;if(!p||!f)return notice('Chưa có dữ liệu đủ để tạo quyết định từ dự báo.','bad');const q=Math.max(0,f.next30+p.min-p.stock);if(transactional(z=>decisionSave(z,{title:`Dự báo: nhập ${q} ${p.name}`,reason:`Bán ${f.units} sản phẩm trong kỳ; dự báo nhu cầu 30 ngày tới ${f.next30}; tồn ${p.stock}, ngưỡng ${p.min}. Số cần cân nhắc nhập = ${q}. Mô hình tốc độ bán; không tính mùa vụ.`,owner:'Quản lý mua hàng',expected:`Kiểm tra báo giá và thời gian giao, sau đó cân nhắc nhập ${q} sản phẩm.`}),'Đã lưu quyết định dựa trên dự báo.'))go('decisions');break;}
 case 'scenario-to-decision':{const sc=scenario(data,ui.scenario,ui.month);if(!sc)return notice('Chưa đủ dữ liệu giá vốn để lưu mô phỏng.','bad');const x=ui.scenario;if(transactional(z=>decisionSave(z,{title:'Mô phỏng cải thiện lợi nhuận',reason:`Cơ sở ${money(sc.baseNet)}; giả định giá bán ${x.pricePct}%, số lượng ${x.unitsPct}%, giá vốn ${x.costPct}%, chi phí ${x.expensesPct}%. Lợi nhuận giả định ${money(sc.net)}, chênh ${money(sc.change)}. Đây không phải dự báo chắc chắn.`,owner:'Quản lý kinh doanh',expected:`Đánh giá biến động lợi nhuận ${money(sc.change)} so với cơ sở.`}),'Đã lưu phương án vào vòng đời quyết định.'))go('decisions');break;}
 case 'buy-from-supplier':ui.prefillSupplier=id;ui.prefillProduct=ui.compareProduct||data.products[0]?.id||'';go('suppliers');openModal('receive');break;
 case 'reset-chat-position':ui.chatPos=null;ui.chatFabPos=null;try{localStorage.removeItem('smartdecision_v3_chatpos');localStorage.removeItem('smartdecision_v4_chatfabpos');}catch{}render();break;
 case 'chat-to-decision':{const reply=[...ui.chat].reverse().find(m=>m.role==='assistant');if(!reply)return notice('Chưa có phân tích để lưu.','bad');if(!confirm('Lưu nội dung phân tích thành đề xuất để bạn xét duyệt? Chưa thực hiện bất kỳ giao dịch nào.'))return;const lastQuestion=[...ui.chat].reverse().find(m=>m.role==='user')?.text||'Đề xuất từ trợ lý';if(transactional(z=>decisionSave(z,{title:lastQuestion.slice(0,110),reason:reply.text.slice(0,1800),owner:'Quản lý',expected:'Kiểm tra tính khả thi trước khi phê duyệt và thực hiện.'}),'Đã lưu phân tích thành đề xuất, chưa thay đổi nghiệp vụ.'))go('decisions');break;}case 'mic':voice();break;default:openModal(act,id);}}
function go(page){if(!pages[page]||page===ui.page)return;
 // Only switch the content. Preserve the user's current sidebar and viewport scroll
 // rather than restoring a stale scroll position from a previous visit to this page.
 ui.page=page;ui.filter='';ui.sidebar=false;render();
}
function download(filename,text,mime){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Đã tạo tệp tải xuống.');}
function submitForm(f){lastMutationOk=true;const fields=normalizeMoneyFields(f,Object.fromEntries(new FormData(f).entries())),a=f.id;switch(a){case 'attach-evidence-form':{const file=f.querySelector('[name="evidence"]')?.files?.[0];if(!file)return notice('Vui lòng chọn ảnh hoặc PDF cần bổ sung.','bad');if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024)return notice('Chứng từ phải là ảnh/PDF tối đa 6 MB.','bad');const ref=String(fields.evidenceRef||'');const known=data.orders.some(o=>'orderproof:'+o.id===ref||(o.payments||[]).some(x=>'orderpay:'+x.id===ref)||(o.refunds||[]).some(x=>'refund:'+x.id===ref))||data.purchases.some(p=>(p.payments||[]).some(x=>'payment:'+x.id===ref)||(p.charges||[]).some(c=>(c.payments||[]).some(x=>'payment:'+x.id===ref)));if(!known)return notice('Không tìm thấy giao dịch cần bổ sung chứng từ.','bad');void commitEvidence(ref,file);closeModal();return;}case 'new-order-form':{const fd=new FormData(f);const ids=fd.getAll('productId'),quant=fd.getAll('quantity');transactional(s=>createOrder(s,{customerId:fields.customerId,status:fields.status,deliveryAddress:fields.deliveryAddress,lines:ids.map((productId,i)=>({productId,quantity:quant[i]}))}),'Đã tạo đơn hàng và cập nhật kho khi hoàn thành.');break;}case 'product-form':{const category=fields.categoryChoice==='__new__'?String(fields.newCategory||'').trim():fields.categoryChoice;
 if(!category){notice('Vui lòng chọn hoặc nhập danh mục sản phẩm.','bad');return;}
 const item={...fields,category,active:fields.active==='yes'};
 transactional(s=>ui.editing?productEdit(s,ui.editing,item):productCreate(s,item),'Đã lưu danh mục sản phẩm.');break;}case 'supplier-form':transactional(s=>ui.editing?supplierEdit(s,ui.editing,fields):supplierCreate(s,fields),'Đã lưu nhà cung cấp.');break;case 'customer-form':transactional(s=>ui.editing?customerEdit(s,ui.editing,fields):customerCreate(s,fields),'Đã lưu khách hàng.');break;case 'confirm-receipt-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Ảnh/PDF tối đa 6 MB.','bad');if(transactional(s=>purchaseReceive(s,fields.purchaseId,fields),'Đã nhận hàng và cập nhật kho, giá vốn, công nợ.'))void commitEvidence('receipt:'+fields.purchaseId,file);break;}
 case 'pay-order-form':case 'refund-order-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Ảnh/PDF tối đa 6 MB.','bad');const isRefund=a==='refund-order-form';if(transactional(s=>isRefund?refundOrder(s,fields):payOrder(s,fields),isRefund?'Đã ghi hoàn tiền cho khách.':'Đã ghi khách thanh toán và cập nhật phải thu.')){const o=data.orders.find(x=>x.id===fields.orderId);const payment=(isRefund?o?.refunds:o?.payments)?.at(-1);if(payment)void commitEvidence((isRefund?'refund:':'orderpay:')+payment.id,file);}break;}
 case 'service-pay-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Ảnh/PDF tối đa 6 MB.','bad');const [purchaseId,chargeId]=String(fields.chargeRef||'').split('|');if(transactional(s=>payServiceCharge(s,{...fields,purchaseId,chargeId}),'Đã thanh toán phí dịch vụ và cập nhật công nợ.')){const charge=data.purchases.find(p=>p.id===purchaseId)?.charges?.find(c=>c.id===chargeId);if(charge?.payments?.length)void commitEvidence('payment:'+charge.payments.at(-1).id,file);}break;}
 case 'receive-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Chứng từ cần là ảnh/PDF tối đa 6 MB.','bad');const paymentFile=f.querySelector?.('[name="paymentEvidence"]')?.files?.[0];if(paymentFile&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(paymentFile.type)||paymentFile.size>6*1024*1024))return notice('Chứng từ chuyển tiền phải là ảnh/PDF tối đa 6 MB.','bad');const freightFile=f.querySelector?.('[name="freightEvidence"]')?.files?.[0],handlingFile=f.querySelector?.('[name="handlingEvidence"]')?.files?.[0];for(const doc of [freightFile,handlingFile])if(doc&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(doc.type)||doc.size>6*1024*1024))return notice('Chứng từ phải là ảnh/PDF tối đa 6 MB.','bad');if(transactional(s=>{let next=s;const entry={...fields};for(const [key,nameField,type] of [['freightPartnerId','newFreightPartnerName','Vận chuyển'],['handlingPartnerId','newHandlingPartnerName','Dịch vụ']]){if(entry[key]==='__new__'){const name=String(entry[nameField]||'').trim();if(!name)throw Error('Vui lòng nhập tên đơn vị nhận phí mới.');const existing=next.suppliers.find(x=>x.name.toLowerCase()===name.toLowerCase());if(existing)entry[key]=existing.id;else{next=supplierCreate(next,{name,type});entry[key]=next.suppliers[0].id;}}}return entry.deliveryStage==='pending'?createPurchaseOrder(next,entry):receiveStock(next,entry);},fields.deliveryStage==='pending'?'Đã lập đơn mua, chờ xác nhận giao hàng.':'Đã nhận hàng, cập nhật kho và công nợ.')){void commitEvidence('purchase:'+data.purchases[0].id,file);const payment=data.purchases[0].payments?.at(-1);if(payment)void commitEvidence('payment:'+payment.id,paymentFile);for(const c of data.purchases[0].charges||[]){const pay=c.payments?.at(-1);if(pay)void commitEvidence('payment:'+pay.id,c.kind==='Vận chuyển'?freightFile:handlingFile);}}break;}case 'pay-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Chứng từ cần là ảnh/PDF tối đa 6 MB.','bad');if(transactional(s=>payPurchase(s,fields),'Đã ghi thanh toán và cập nhật công nợ.')){const purchase=data.purchases.find(x=>x.id===fields.purchaseId),last=purchase?.payments?.at(-1);if(last)void commitEvidence('payment:'+last.id,file);}break;}case 'audit-form':{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Chứng từ phải là ảnh/PDF tối đa 6 MB.','bad');if(transactional(s=>auditStock(s,fields),'Đã ghi kiểm kê và cập nhật tồn kho.'))void commitEvidence('audit:'+data.stockLedger[0].id,file);break;}case 'expense-form':{const category=fields.expenseCategoryChoice==='__new__'?String(fields.newExpenseCategory||'').trim():(fields.expenseCategoryChoice||fields.category);if(!category)return notice('Vui lòng nhập tên nhóm chi phí mới.','bad');{const file=f.querySelector?.('[name="evidence"]')?.files?.[0];if(file&&(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>6*1024*1024))return notice('Chứng từ phải là ảnh/PDF tối đa 6 MB.','bad');const id=ui.editing;if(transactional(s=>expenseSave(s,{...fields,category,id:id||undefined}),'Đã ghi nhận chi phí và cập nhật báo cáo.'))void commitEvidence('expense:'+(id||data.expenses[0].id),file);}break;}case 'decision-form':transactional(s=>decisionSave(s,{...fields,id:ui.editing||undefined}),'Đã lưu quyết định.');break;case 'rate-form':{const scores={price:Number(fields.price),delivery:Number(fields.delivery),quality:Number(fields.quality)};if(Object.values(scores).some(z=>!Number.isInteger(z)||z<1||z>5))return notice('Điểm phải nằm trong khoảng 1–5.','bad');const s=structuredClone(data);s.ratings[ui.editing]=scores;setData(s,'Đã cập nhật đánh giá nhà cung cấp.');break;}case 'settings-form':{if(!fields.name.trim())return notice('Cần nhập tên doanh nghiệp.','bad');const s=structuredClone(data);s.company={...s.company,...fields};setData(s,'Đã lưu tên và thông tin doanh nghiệp.');return;}case 'weights-form':{const w={price:Number(fields.price),delivery:Number(fields.delivery),quality:Number(fields.quality)};if(Object.values(w).some(z=>!Number.isSafeInteger(z)||z<0||z>100)||Object.values(w).every(z=>z===0))return notice('Trọng số hợp lệ 0–100 và có ít nhất một trọng số dương.','bad');const s=structuredClone(data);s.weights=w;setData(s,'Đã cập nhật trọng số đánh giá.');return;}case 'scenario-form':{const x=Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,Number(v)]));if(Object.values(x).some(z=>!Number.isFinite(z))||x.unitsPct < -100||x.pricePct < -80||x.costPct < -80||x.expensesPct < -100)return notice('Giả định không hợp lệ.','bad');ui.scenario=x;render();return;}case 'compare-supplier-form':ui.compareProduct=fields.productId;ui.compareQty=Number(fields.quantity);if(!Number.isSafeInteger(ui.compareQty)||ui.compareQty<1)return notice('Nhập số lượng nguyên dương.','bad');render();return;case 'goal-form':{if(!Number.isFinite(Number(fields.goal))||Number(fields.goal)<0)return notice('Mục tiêu không hợp lệ.','bad');ui.goal=Number(fields.goal);render();return;}case 'chat-form':ui.chatInput='';sendChat(fields.question);return;default:return;}if(ui.modal&&lastMutationOk)closeModal();}
function localDss(question){const a=simpleRecommendation(data),q=String(question||'').toLowerCase();let lines=['Phân tích dữ liệu tại cửa hàng:'];if(/kho|nhập|tồn|hàng/.test(q)){lines.push(`• ${a.low.length} sản phẩm chạm ngưỡng cảnh báo.`);for(const p of a.low.slice(0,5))lines.push(`• ${p.name}: còn ${p.stock}, ngưỡng ${p.min}, thiếu tối thiểu ${Math.max(0,p.min-p.stock)} đơn vị.`);lines.push('Khuyến nghị có điều kiện: kiểm tra nhu cầu dự kiến và báo giá NCC trước khi duyệt phiếu nhập.');}else if(/công nợ|nhà cung cấp|thanh toán/.test(q)){lines.push(`• Tổng công nợ từ phiếu mua: ${money(a.debts.reduce((z,x)=>z+x.debt,0))}.`);a.debts.slice(0,4).forEach(x=>lines.push(`• ${x.name}: ${money(x.debt)}.`));lines.push('Thanh toán nợ làm giảm phải trả, không làm giảm lợi nhuận thêm lần nữa.');}else{lines.push(`• Doanh thu đơn hoàn thành: ${money(a.revenue)}.`);lines.push(`• Chi phí hoạt động: ${money(a.expense)}.`);lines.push(`• Lợi nhuận trước thuế: ${a.profit===null?'chưa xác minh do đơn thiếu giá vốn':money(a.profit)}.`);lines.push(`• ${a.low.length} SKU cần chú ý tồn kho; ${a.unverified} đơn thiếu giá vốn.`);lines.push('Để quyết định: vào Mô phỏng phương án so sánh các giả định, rồi lưu quyết định và theo dõi kết quả.');}return lines.join('\n');}
async function sendChat(question){const q=String(question||'').trim();if(!q||ui.chatBusy)return;ui.chatOpen=true;ui.chat.push({role:'user',text:q});ui.chatBusy=true;render();scrollChat();const f=financials(data);const context={company:{sector:data.company.sector},products:data.products.map(p=>({sku:p.sku,name:p.name,stock:p.stock,min:p.min,price:p.price,cost:p.cost})).slice(0,100),finance:{revenue:f.revenue,verifiedCogs:f.cogsKnown,operatingExpenses:f.expenses,profit:f.net,missingCostOrders:f.missing.length,cashPaidSupplier:procurementSummary(data).paidSupplier,cashPaidFreight:procurementSummary(data).paidExternal,recordedCashOutflow:f.expenses+procurementSummary(data).paidSupplier+procurementSummary(data).paidExternal},lowStock:simpleRecommendation(data).low.map(p=>({name:p.name,stock:p.stock,min:p.min})),supplierDebts:data.suppliers.map(s=>({supplier:s.name,payable:supplierDebt(data,s.id)})),customerReceivables:customerReceivables(data),deliveryPerformance:data.suppliers.map(s=>({name:s.name,shippingPolicy:supplierPolicies(s),...supplierDeliveryStats(data,s.id)})),decisionCount:data.decisions.length,limitations:'Dữ liệu cục bộ; một số đơn lịch sử thiếu giá vốn. Không suy đoán dữ liệu thiếu. Không có thông tin nhận dạng khách hàng.'};try{const response=await fetch('/.netlify/functions/decision-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,context,history:ui.chat.slice(0,-1).slice(-6).map(m=>({role:m.role,content:m.text}))})});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error(result.error||`HTTP ${response.status}`);ui.chat.push({role:'assistant',text:result.answer||'Gemini chưa tạo được câu trả lời.',source:'gemini'});}catch(e){ui.chat.push({role:'assistant',text:`Gemini đang tạm gián đoạn. Dưới đây là kết quả tính trực tiếp từ dữ liệu hệ thống:\n\n${localDss(q)}`,source:'local'});}finally{ui.chatBusy=false;render();scrollChat();}}
function scrollChat(){requestAnimationFrame(()=>{const el=document.getElementById('chat-body');if(el)el.scrollTop=el.scrollHeight;});}
function voice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!window.isSecureContext)return notice('Micro cần HTTPS.','bad');if(!Speech)return notice('Trình duyệt chưa hỗ trợ nhận dạng giọng nói.','bad');const r=new Speech();r.lang='vi-VN';r.onresult=e=>{const t=e.results?.[0]?.[0]?.transcript||'';const x=document.querySelector('#chat-form input');if(x)x.value=(x.value?x.value+' ':'')+t;};r.onerror=e=>notice(`Micro: ${e.error}`,'bad');r.start();notice('Đang nghe giọng nói tiếng Việt…');}
// Single document event delegation, avoiding inline script / onClick injection.
document.addEventListener('click',e=>{const goEl=e.target.closest('[data-go]');if(goEl){go(goEl.dataset.go);return;}const ch=e.target.closest('[data-chat-prompt]');if(ch){sendChat(ch.dataset.chatPrompt);return;}const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='close-modal'&&e.target.closest('.modal')&&e.target===b.closest('.modal-backdrop'))return;if(b.classList.contains('modal-backdrop')&&e.target!==b)return;const name=b.dataset.action;if(name==='toggle-chat'&&b.classList.contains('chat-fab')&&ignoreFabClick){ignoreFabClick=false;return;}if(name==='remove-line'){const all=document.querySelectorAll('.order-line');if(all.length>1)b.closest('.order-line')?.remove();return;}action(name,b.dataset.id||'');});
document.addEventListener('submit',e=>{e.preventDefault();try{submitForm(e.target);}catch(err){notice(err.message||'Có lỗi xử lý dữ liệu.','bad');}});
document.addEventListener('change',e=>{const x=e.target;
 if((x.name==='freightPartnerId'||x.name==='handlingPartnerId')&&x.closest?.('#receive-form')){const label=x.parentElement?.nextElementSibling;const inp=label?.querySelector('input');if(label&&label.classList.contains('quick-partner')){const adding=x.value==='__new__';label.hidden=!adding;if(inp){inp.required=adding;if(adding)inp.focus();}}return;}
 if(x.name==='expenseCategoryChoice'){const f=x.closest('.expense-category-control')?.querySelector('.expense-category-new'),inp=f?.querySelector('input');if(f){f.hidden=x.value!=='__new__';if(inp){inp.required=x.value==='__new__';if(x.value==='__new__')inp.focus();}}return;}
 if(x.name==='categoryChoice'){const wrap=x.closest('.category-control');const field=wrap?.querySelector('.category-new'),inp=field?.querySelector('input');if(field){field.hidden=x.value!=='__new__';if(inp){inp.required=x.value==='__new__';if(x.value==='__new__')inp.focus();}}return;}
 if(x.name==='customerId'&&x.closest?.('#new-order-form')){const c=data.customers.find(v=>v.id===x.value),field=x.closest('form')?.querySelector('[name="deliveryAddress"]');if(field)field.value=c?.address||'';return;}
 if(x.name==='supplierId'&&x.closest?.('#receive-form')){applyShippingPolicy();return;}
 if(x.name==='productId'&&x.closest?.('#receive-form')){const p=data.products.find(v=>v.id===x.value),recent=data.purchases.find(v=>v.productId===x.value);const f=x.closest('form');if(f){const cost=f.querySelector('[name="unitCost"]');if(cost)cost.value=formatVndInput(recent?.unitCost??p?.lastPurchasePrice??0);const supplier=f.querySelector('[name="supplierId"]');if(supplier&&p?.supplierId)supplier.value=p.supplierId;}updatePurchasePreview();return;}
 if(x.closest?.('#receive-form'))updatePurchasePreview();
 if(x.matches('[data-order-status]')){const id=x.dataset.orderStatus;const order=data.orders.find(o=>o.id===id);if(!order)return;transactional(s=>updateOrderStatus(s,id,x.value),'Đã cập nhật trạng thái đơn và tồn kho liên quan.');if(data.orders.find(o=>o.id===id)?.status!==x.value)render();}else if(x.matches('[data-forecast-product]')){ui.forecastProduct=x.value;render();}else if(x.matches('[data-filter-month]')){ui.month=x.value;render();}else if(x.id==='restore-file'){const f=x.files?.[0];if(!f)return;if(f.size>65_000_000)return notice('Tệp sao lưu quá lớn (tối đa 65 MB).','bad');f.text().then(text=>{const pack=JSON.parse(text);const v=pack.schema==='smartdecision-local-v1'?migrateLegacyBackup(pack):validateData(pack.schema==='smartdecision-v3'?pack.data:pack);if(!confirm('Khôi phục sẽ thay thế dữ liệu hiện tại. Bạn đã sao lưu chưa?'))return;setData(v,'Đã khôi phục bản sao lưu dữ liệu.');if(Array.isArray(pack.evidence)&&pack.evidence.length)restoreEvidence(pack.evidence).then(n=>notice(`Đã nhập thêm ${n} chứng từ.`)).catch(err=>notice('Dữ liệu đã khôi phục nhưng chứng từ có lỗi: '+err.message,'bad'));}).catch(err=>notice(`Không thể nhập dữ liệu: ${err.message}`,'bad'));}});
document.addEventListener('input',e=>{if(e.target.matches?.('[data-money]'))formatMoneyElement(e.target);if(e.target.closest?.('#receive-form'))updatePurchasePreview();if(e.target.name==='price'&&e.target.closest?.('#product-form'))updatePricingPreview();if(e.target.id==='page-search'){const old=e.target.selectionStart;ui.filter=e.target.value;const sc=window.scrollY;render();const x=document.getElementById('page-search');if(x){x.focus();x.setSelectionRange(old,old);}window.scrollTo(0,sc);}});
// Prevent number wheel changes on focused fields.
document.addEventListener('wheel',e=>{if(e.target.matches?.('input[type="number"]')&&document.activeElement===e.target)e.preventDefault();},{passive:false});
let dragging=null;let ignoreFabClick=false;
document.addEventListener('pointerdown',e=>{
 const handle=e.target.closest?.('#chat-handle');const fab=e.target.closest?.('.chat-fab');
 if((!handle&&!fab)||(handle&&e.target.closest?.('button')))return;
 const node=(handle||fab).closest(handle?'.chat-panel':'.chat-fab');if(!node)return;
 const r=node.getBoundingClientRect();dragging={pointer:e.pointerId,node,kind:handle?'panel':'fab',x:r.left,y:r.top,startX:e.clientX,startY:e.clientY,moved:false};
 (handle||fab).setPointerCapture?.(e.pointerId);
});
document.addEventListener('pointermove',e=>{
 if(!dragging||dragging.pointer!==e.pointerId)return;
 const d=dragging,dx=e.clientX-d.startX,dy=e.clientY-d.startY;if(Math.abs(dx)+Math.abs(dy)>5)d.moved=true;
 if(!d.moved)return;if(e.cancelable)e.preventDefault();
 const x=Math.max(0,Math.min(innerWidth-d.node.offsetWidth,d.x+dx));const y=Math.max(0,Math.min(innerHeight-d.node.offsetHeight,d.y+dy));
 d.node.style.left=x+'px';d.node.style.top=y+'px';d.node.style.right='auto';d.node.style.bottom='auto';
 if(d.kind==='panel')ui.chatPos={x,y};else ui.chatFabPos={x,y};
});
document.addEventListener('pointerup',e=>{
 if(!dragging||dragging.pointer!==e.pointerId)return;
 if(dragging.kind==='fab'&&dragging.moved)ignoreFabClick=true;
 try{localStorage.setItem('smartdecision_v3_chatpos',JSON.stringify(ui.chatPos));localStorage.setItem('smartdecision_v4_chatfabpos',JSON.stringify(ui.chatFabPos));}catch{}
 dragging=null;
});
document.addEventListener('pointercancel',()=>{dragging=null;});

render();
